package com.locallaunch.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.Collections;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwtService; public JwtAuthenticationFilter(JwtService j){jwtService=j;} @Override protected boolean shouldNotFilter(HttpServletRequest request){String p=request.getServletPath(); return p.equals("/api/users/register")||p.equals("/api/users/login")||p.startsWith("/api/businesses/public/")||p.startsWith("/api/enquiries/public/")||p.startsWith("/api/ratings/public/");} @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization"); if(h==null||!h.startsWith("Bearer ")){chain.doFilter(req,res);return;} try{String email=jwtService.extractEmail(h.substring(7));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(email,null, Collections.emptyList()));chain.doFilter(req,res);}catch(Exception e){res.setStatus(401);res.setContentType("application/json");res.getWriter().write("{\"status\":401,\"message\":\"Invalid or expired token\"}");}} }
